"use client";

import * as React from "react";
import {
  ArrowUp,
  Folder,
  Gauge,
  GitBranch,
  Hand,
  ListChecks,
  Mic,
  Plus,
  ShieldAlert,
  Square,
} from "lucide-react";
import { ModelPicker, type ModelOption } from "./model-picker";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * AGENT COMPOSER: the taller composer for agent surfaces
 *
 *   status      a tab hangs off the card's top edge with the
 *               branch, the project folder and how full the
 *               context is; each morphs when it changes, and the
 *               context ring fills, turning amber past 80%
 *   prompt      type; Enter sends, Shift+Enter adds a line, and
 *               the field grows with the text
 *   permission  the pill under the prompt says how much the agent
 *               may do on its own (Auto, Ask first, Plan only,
 *               Full access) and grows into a list with a line on
 *               each, clear of the composer
 *   model       the model pill on the right grows into its own
 *               list, with thinking effort for models that reason
 *   send        the arrow blurs into a spinner, then into Stop;
 *               the mic beside it breathes while it listens
 *   files       + opens the file picker, and paste and drop work
 *               too; chips fold open above the prompt
 *
 * status takes useChat's status as is.
 * ───────────────────────────────────────────────────────── */

export type AgentComposerStatus = "ready" | "submitted" | "streaming" | "error";

export interface AgentComposerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSubmit" | "defaultValue"
> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onSubmit: (value: string) => void;
  onStop?: () => void;
  /** Pass useChat's status straight through. */
  status?: AgentComposerStatus;
  placeholder?: string;
  /** The tab on top. Leave all three out and there's no tab. */
  branch?: string;
  folder?: string;
  context?: { used: number; limit: number };
  /** The permission modes; defaults to Auto, Ask first, Plan only and Full access. */
  permissions?: ModelOption[];
  permission?: string;
  defaultPermission?: string;
  onPermissionChange?: (id: string) => void;
  models: ModelOption[];
  model: string;
  onModelChange: (id: string) => void;
  effort?: string;
  onEffortChange?: (effort: string) => void;
  /** Enables +, paste and drop. */
  onFilesSelected?: (files: File[]) => void;
  accept?: string;
  /** Attachment chips, shown above the prompt. */
  attachments?: React.ReactNode;
  /** Shows the mic. */
  onVoice?: () => void;
  listening?: boolean;
}

export const AGENT_PERMISSIONS: ModelOption[] = [
  {
    id: "auto",
    name: "Auto",
    description: "Decides for itself, asks when it's unsure",
    icon: <Gauge />,
  },
  {
    id: "ask",
    name: "Ask first",
    description: "Checks with you before every change",
    icon: <Hand />,
  },
  {
    id: "plan",
    name: "Plan only",
    description: "Reads and plans, changes nothing",
    icon: <ListChecks />,
  },
  {
    id: "full",
    name: "Full access",
    description: "Runs everything without asking",
    icon: <ShieldAlert />,
  },
];

const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const compactNumber = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 1,
});

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function Fold({
  show,
  reduced,
  children,
}: {
  show: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [last, setLast] = React.useState(children);
  if (show && children !== last) setLast(children);
  return (
    <div
      aria-hidden={!show || undefined}
      inert={!show}
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        opacity: show ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 380ms ${MORPH}, opacity ${show ? "280ms" : "140ms"} ${MORPH}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">{show ? children : last}</div>
    </div>
  );
}

/** How full the context is: a small ring that fills, amber past 80% and red past 95%, with the share rolling beside it. */
function ContextMeter({
  used,
  limit,
  reduced,
}: {
  used: number;
  limit: number;
  reduced: boolean;
}) {
  const share = limit ? Math.min(1, used / limit) : 0;
  const c = 2 * Math.PI * 5;
  const tone =
    share >= 0.95
      ? "text-red-500"
      : share >= 0.8
        ? "text-amber-500"
        : "text-foreground/60";
  return (
    <span
      className="flex items-center gap-1.5"
      title={`${compactNumber.format(used)} of ${compactNumber.format(limit)} tokens`}
    >
      <svg
        viewBox="0 0 14 14"
        aria-hidden="true"
        className={`size-3.5 -rotate-90 transition-colors duration-300 ${tone}`}
      >
        <circle
          cx="7"
          cy="7"
          r="5"
          fill="none"
          stroke="currentColor"
          strokeOpacity="0.2"
          strokeWidth="2"
        />
        <circle
          cx="7"
          cy="7"
          r="5"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeDasharray={c}
          style={{
            strokeDashoffset: c * (1 - share),
            transition: reduced ? "none" : `stroke-dashoffset 600ms ${MORPH}`,
          }}
        />
      </svg>
      <span className="tabular-nums">
        <NumberRoll
          value={share}
          format={{ style: "percent" }}
          duration={600}
        />
      </span>
      <span className="sr-only">of the context used</span>
    </span>
  );
}

export function AgentComposer({
  value,
  defaultValue = "",
  onValueChange,
  onSubmit,
  onStop,
  status = "ready",
  placeholder = "What should we build?",
  branch,
  folder,
  context,
  permissions = AGENT_PERMISSIONS,
  permission,
  defaultPermission,
  onPermissionChange,
  models,
  model,
  onModelChange,
  effort,
  onEffortChange,
  onFilesSelected,
  accept,
  attachments,
  onVoice,
  listening = false,
  className = "",
  ...props
}: AgentComposerProps) {
  const reduced = useReducedMotion();
  const [own, setOwn] = React.useState(defaultValue);
  const [ownPermission, setOwnPermission] = React.useState(
    defaultPermission ?? permissions[0]?.id ?? "",
  );
  const [dragging, setDragging] = React.useState(false);
  const text = value ?? own;
  const chosenPermission = permission ?? ownPermission;
  const cardRef = React.useRef<HTMLFormElement>(null);
  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileRef = React.useRef<HTMLInputElement>(null);
  const busy = status === "submitted" || status === "streaming";
  const canSend = !busy && text.trim().length > 0;
  const hasTab = Boolean(branch || folder || context);

  const setText = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  React.useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 220)}px`;
  }, [text]);

  const submit = () => {
    if (!canSend) return;
    onSubmit(text);
    if (value === undefined) setOwn("");
  };

  const takeFiles = (list: FileList | null) => {
    if (!list || list.length === 0 || !onFilesSelected) return false;
    onFilesSelected(Array.from(list));
    return true;
  };

  const action = busy
    ? status === "streaming" && onStop
      ? "stop"
      : "wait"
    : "send";

  return (
    <div className={`w-full ${className}`} {...props}>
      {/* The tab: where the agent is working, and how full its context is. */}
      {hasTab && (
        <div className="mx-3.5 flex h-7 items-center gap-3 rounded-t-[12px] bg-muted px-3 text-[11.5px] text-muted-foreground">
          {branch && (
            <span className="flex min-w-0 items-center gap-1.5">
              <GitBranch aria-hidden="true" className="size-3.5 shrink-0" />
              <span className="sr-only">Branch</span>
              <span className="truncate">
                <TextMorph>{branch}</TextMorph>
              </span>
            </span>
          )}
          {folder && (
            <span className="flex min-w-0 items-center gap-1.5">
              <Folder aria-hidden="true" className="size-3.5 shrink-0" />
              <span className="sr-only">Project</span>
              <span className="truncate">
                <TextMorph>{folder}</TextMorph>
              </span>
            </span>
          )}
          {context && (
            <span className="ml-auto shrink-0">
              <ContextMeter
                used={context.used}
                limit={context.limit}
                reduced={reduced}
              />
            </span>
          )}
        </div>
      )}

      <form
        ref={cardRef}
        onSubmit={(e) => {
          e.preventDefault();
          submit();
        }}
        onDragOver={(e) => {
          if (!onFilesSelected || !e.dataTransfer.types.includes("Files"))
            return;
          e.preventDefault();
          setDragging(true);
        }}
        onDragLeave={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node))
            setDragging(false);
        }}
        onDrop={(e) => {
          if (!onFilesSelected) return;
          e.preventDefault();
          setDragging(false);
          takeFiles(e.dataTransfer.files);
        }}
        className={`@container relative rounded-[20px] bg-background p-1.5 transition-shadow duration-200 ${
          dragging
            ? "shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_40%,transparent)]"
            : "shadow-[0_0_0_1px_var(--border)] focus-within:shadow-[0_0_0_1px_color-mix(in_oklab,var(--foreground)_22%,transparent)]"
        }`}
      >
        <Fold show={Boolean(attachments)} reduced={reduced}>
          <div className="flex flex-wrap gap-2 px-2 pt-2">{attachments}</div>
        </Fold>

        <textarea
          ref={textareaRef}
          rows={1}
          value={text}
          placeholder={placeholder}
          aria-label={placeholder}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (
              e.key === "Enter" &&
              !e.shiftKey &&
              !e.nativeEvent.isComposing
            ) {
              e.preventDefault();
              submit();
            }
          }}
          onPaste={(e) => {
            if (
              takeFiles(e.clipboardData.files) &&
              !e.clipboardData.getData("text")
            )
              e.preventDefault();
          }}
          className="block max-h-[220px] w-full resize-none overflow-y-auto bg-transparent px-2.5 pb-2 pt-2 text-[14px] leading-6 text-foreground outline-none placeholder:text-muted-foreground"
        />

        <div className="flex items-center gap-0.5">
          {onFilesSelected && (
            <>
              <button
                type="button"
                aria-label="Add files"
                onClick={() => fileRef.current?.click()}
                className={`cursor-pointer flex size-7 shrink-0 items-center justify-center rounded-full bg-muted text-foreground transition-colors hover:bg-accent @min-[26rem]:size-8 ${FOCUS}`}
              >
                <Plus className="size-4" />
              </button>
              <input
                ref={fileRef}
                type="file"
                multiple
                accept={accept}
                className="hidden"
                onChange={(e) => {
                  takeFiles(e.target.files);
                  e.target.value = "";
                }}
              />
            </>
          )}
          <ModelPicker
            label="Permission"
            models={permissions}
            value={chosenPermission}
            onValueChange={(id) => {
              if (permission === undefined) setOwnPermission(id);
              onPermissionChange?.(id);
            }}
            anchorRef={cardRef}
            side="top"
            align="start"
          />

          <div className="ml-auto flex items-center gap-0.5 @min-[26rem]:gap-1">
            <ModelPicker
              label="Model"
              models={models}
              value={model}
              onValueChange={onModelChange}
              effort={effort}
              onEffortChange={onEffortChange}
              anchorRef={cardRef}
              side="top"
              align="end"
            />
            {onVoice && (
              <button
                type="button"
                aria-label={listening ? "Stop listening" : "Speak"}
                aria-pressed={listening}
                onClick={onVoice}
                // On the narrowest composers the mic steps aside so Send always fits.
                className={`cursor-pointer relative hidden size-7 shrink-0 items-center justify-center rounded-full transition-colors duration-200 @min-[22rem]:flex @min-[26rem]:size-8 ${FOCUS} ${
                  listening
                    ? "text-primary"
                    : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent"
                }`}
              >
                {/* Breathes only while it listens. */}
                <span
                  aria-hidden="true"
                  className="absolute inset-0 rounded-full bg-primary/12"
                  style={{
                    opacity: listening ? 1 : 0,
                    animation:
                      listening && !reduced
                        ? "ui-breathe 1.6s ease-in-out infinite"
                        : "none",
                    transition: `opacity 200ms ${MORPH}`,
                  }}
                />
                <Mic className="relative size-4" />
              </button>
            )}
            <button
              type={action === "send" ? "submit" : "button"}
              aria-label={
                action === "stop"
                  ? "Stop"
                  : action === "wait"
                    ? "Sending"
                    : "Send"
              }
              disabled={action === "send" ? !canSend : action === "wait"}
              onClick={action === "stop" ? onStop : undefined}
              className={`cursor-pointer disabled:cursor-default relative flex size-8 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground transition-[opacity,transform] duration-200 active:scale-95 disabled:opacity-35 ${FOCUS}`}
            >
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "send", reduced)}
              >
                <ArrowUp className="size-4" />
              </span>
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "stop", reduced)}
              >
                <Square fill="currentColor" className="size-3" />
              </span>
              <span
                aria-hidden="true"
                className="absolute inset-0 flex items-center justify-center"
                style={swap(action === "wait", reduced)}
              >
                <span
                  className={`size-3.5 rounded-full border-[1.5px] border-current/35 border-t-current motion-reduce:animate-none ${action === "wait" ? "animate-spin" : ""}`}
                />
              </span>
            </button>
          </div>
        </div>

        <div
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 flex items-center justify-center rounded-[20px] bg-background/85 text-[13px] font-medium text-foreground"
          style={{
            opacity: dragging ? 1 : 0,
            transition: reduced ? "none" : `opacity 200ms ${MORPH}`,
          }}
        >
          Drop files to attach
        </div>
      </form>
    </div>
  );
}

"use client";

import * as React from "react";
import { Check, ChevronDown } from "lucide-react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * MODEL PICKER: the pill grows into the menu
 *
 *   closed   a quiet pill in the composer toolbar: model and
 *            thinking effort; both morph when they change, and
 *            the model's icon trades places through a blur
 *   open     a copy of the pill lifts clear of the composer and
 *            unfolds into the list: each model with a line on
 *            what it's for, speed and smarts
 *   effort   models that reason get a Thinking control; the
 *            panel's height follows
 *   locked   paid models show "Pro" and call onLockedSelect
 *
 * One surface: opening grows the pill's size and radius into the
 * panel while the label cross-fades into the list, and closing
 * folds it back into the pill. It never covers the composer:
 * pass anchorRef and it opens above it, lined up with its edge.
 * ───────────────────────────────────────────────────────── */

export interface ModelOption {
  id: string;
  name: string;
  /** What it's for, e.g. "Fast, everyday questions". */
  description?: string;
  icon?: React.ReactNode;
  /** 1 to 3. */
  speed?: number;
  /** 1 to 3. */
  intelligence?: number;
  /** Supports a thinking-effort setting. */
  reasoning?: boolean;
  /** Needs an upgrade; shows "Pro". */
  locked?: boolean;
}

export interface ModelPickerProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  models: ModelOption[];
  value: string;
  onValueChange: (id: string) => void;
  /** Thinking effort for reasoning models; shown when onEffortChange is set. */
  effort?: string;
  onEffortChange?: (effort: string) => void;
  efforts?: string[];
  /** Called instead of selecting a locked model, e.g. to open pricing. */
  onLockedSelect?: (model: ModelOption) => void;
  /** Grow upward (composers at the bottom) or downward. */
  side?: "top" | "bottom";
  /** Grow from the pill's left edge or its right edge. */
  align?: "start" | "end";
  /** Space to keep from the viewport edges on narrow screens. */
  collisionPadding?: number;
  /** Open clear of this element (e.g. your composer) and line up with its edge, instead of over it. */
  anchorRef?: React.RefObject<HTMLElement | null>;
  disabled?: boolean;
  /** What the choice is, for screen readers: "Model" by default, e.g. "Permission" for a permissions picker. */
  label?: string;
}

type Phase = "closed" | "opening" | "open" | "closing";

const EFFORTS = ["Low", "Medium", "High"];
const EASE = "cubic-bezier(0.23,1,0.32,1)";
const DURATION = 380;
const PANEL_WIDTH = 340;
const GAP = 8;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Meter({ value = 0, label }: { value?: number; label: string }) {
  return (
    <span
      className="flex w-[38px] shrink-0 items-center justify-center gap-[3px]"
      title={`${label}: ${value} of 3`}
    >
      {[1, 2, 3].map((n) => (
        <span
          key={n}
          aria-hidden="true"
          className={`h-[5px] w-[7px] rounded-full ${n <= value ? "bg-foreground/70" : "bg-border"}`}
        />
      ))}
      <span className="sr-only">
        {label} {value} of 3
      </span>
    </span>
  );
}

const MORPH = "cubic-bezier(0.16,1,0.3,1)";

/** The model's icon: a new one rises out of a blur while the old one shrinks away. */
function ModelIcon({
  id,
  icon,
  reduced,
}: {
  id: string;
  icon: React.ReactNode;
  reduced: boolean;
}) {
  const [items, setItems] = React.useState([{ id, icon, initial: true }]);
  if (items[items.length - 1].id !== id)
    setItems([...items.slice(-1), { id, icon, initial: false }]);
  return (
    <span
      aria-hidden="true"
      className="relative flex size-4 items-center justify-center text-muted-foreground [&_svg]:size-4 [&_svg]:stroke-[1.8]"
    >
      {items.map((item) => (
        <IconLayer
          key={item.id}
          on={item.id === id}
          enter={!item.initial && !reduced}
          reduced={reduced}
        >
          {item.icon}
        </IconLayer>
      ))}
    </span>
  );
}

function IconLayer({
  on,
  enter,
  reduced,
  children,
}: {
  on: boolean;
  enter: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const [entering] = React.useState(enter);
  React.useLayoutEffect(() => {
    if (!entering) return;
    ref.current?.animate(
      [
        { opacity: 0, transform: "scale(0.6)", filter: "blur(3px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 380, easing: MORPH, fill: "backwards" },
    );
  }, [entering]);
  return (
    <span
      ref={ref}
      className="absolute inset-0 flex items-center justify-center"
      style={{
        opacity: on ? 1 : 0,
        transform: on ? "none" : "scale(0.6)",
        filter: on ? "none" : "blur(3px)",
        transition: reduced
          ? "none"
          : `opacity 200ms ${MORPH}, transform 380ms ${MORPH}, filter 200ms ${MORPH}`,
      }}
    >
      {children}
    </span>
  );
}

function PillLabel({
  model,
  effort,
  reduced,
}: {
  model?: ModelOption;
  effort?: string;
  reduced: boolean;
}) {
  // The effort opens beside the name for models that reason, and folds away (keeping its word) for those that don't.
  const showEffort = Boolean(model?.reasoning && effort);
  const [lastEffort, setLastEffort] = React.useState(effort);
  if (effort && effort !== lastEffort) setLastEffort(effort);
  return (
    <>
      {model?.icon && (
        <ModelIcon id={model.id} icon={model.icon} reduced={reduced} />
      )}
      <span className="whitespace-nowrap text-foreground">
        <TextMorph>{model?.name ?? "Choose a model"}</TextMorph>
      </span>
      <span
        className="-ml-1.5 grid"
        style={{
          gridTemplateColumns: showEffort ? "1fr" : "0fr",
          opacity: showEffort ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-columns 380ms ${MORPH}, opacity ${showEffort ? "280ms" : "140ms"} ${MORPH}`,
        }}
      >
        <span className="min-w-0 overflow-hidden whitespace-nowrap pl-1.5 text-muted-foreground">
          <TextMorph>{effort ?? lastEffort ?? ""}</TextMorph>
        </span>
      </span>
    </>
  );
}

export function ModelPicker({
  models,
  value,
  onValueChange,
  effort,
  onEffortChange,
  efforts = EFFORTS,
  onLockedSelect,
  side = "top",
  align = "start",
  collisionPadding = 16,
  anchorRef,
  disabled = false,
  label = "Model",
  className = "",
  ...props
}: ModelPickerProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const selected = models.find((m) => m.id === value);
  const [phase, setPhase] = React.useState<Phase>("closed");
  const [active, setActive] = React.useState(0);
  const [pill, setPill] = React.useState({ width: 0, height: 32 });
  const [panelHeight, setPanelHeight] = React.useState(0);
  // The panel's width and sideways shift, so it always fits the screen.
  const [fit, setFit] = React.useState({
    width: PANEL_WIDTH,
    shift: 0,
    lift: 0,
  });
  const [highlight, setHighlight] = React.useState({ top: 0, ready: false });
  const [segment, setSegment] = React.useState({
    left: 0,
    width: 0,
    ready: false,
  });
  // After a mouse choice, focus returns to the pill without a keyboard focus ring.
  const [quietFocus, setQuietFocus] = React.useState(false);

  const wrapRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const rowRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const segmentRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const timer = React.useRef(0);

  const expanded = phase === "open";
  const mounted = phase !== "closed";
  const [prevPhase, setPrevPhase] = React.useState(phase);
  if (phase !== prevPhase) {
    setPrevPhase(phase);
    if (phase === "closed") {
      setHighlight({ top: 0, ready: false });
    }
  }
  const showEffort = Boolean(onEffortChange && selected?.reasoning);

  /* Where the open panel sits: lifted clear of the anchor (the pill itself by default), lined up
   * with the anchor's edge, and narrowed or shifted so it never leaves the screen. */
  const measureFit = React.useCallback(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const rect = wrap.getBoundingClientRect();
    const edge = (anchorRef?.current ?? wrap).getBoundingClientRect();
    const viewport = document.documentElement.clientWidth;
    const width = Math.min(PANEL_WIDTH, viewport - collisionPadding * 2);
    const lift =
      side === "top"
        ? rect.bottom - edge.top + GAP
        : edge.bottom - rect.top + GAP;
    let shift: number;
    if (align === "start") {
      const left = Math.min(
        Math.max(edge.left, collisionPadding),
        viewport - collisionPadding - width,
      );
      shift = left - rect.left;
    } else {
      const right = Math.max(
        Math.min(edge.right, viewport - collisionPadding),
        collisionPadding + width,
      );
      shift = right - rect.right;
    }
    setFit((f) =>
      f.width === width && f.shift === shift && f.lift === lift
        ? f
        : { width, shift, lift },
    );
  }, [align, side, collisionPadding, anchorRef]);

  const open = () => {
    if (disabled || phase === "open" || phase === "opening") return;
    window.clearTimeout(timer.current);
    measureFit();
    setActive(
      Math.max(
        0,
        models.findIndex((m) => m.id === value),
      ),
    );
    setPhase(reduced ? "open" : "opening");
  };

  const close = React.useCallback(
    (refocus = true) => {
      window.clearTimeout(timer.current);
      if (refocus) triggerRef.current?.focus({ preventScroll: true });
      if (reduced) {
        setPhase("closed");
        return;
      }
      setPhase("closing");
      timer.current = window.setTimeout(() => setPhase("closed"), DURATION);
    },
    [reduced],
  );

  // Opening: paint the surface at the pill's size first, then let it grow.
  React.useEffect(() => {
    if (phase !== "opening") return;
    let inner = 0;
    const outer = requestAnimationFrame(() => {
      inner = requestAnimationFrame(() => setPhase("open"));
    });
    return () => {
      cancelAnimationFrame(outer);
      cancelAnimationFrame(inner);
    };
  }, [phase]);

  React.useEffect(() => () => window.clearTimeout(timer.current), []);

  React.useEffect(() => {
    if (!mounted) return;
    window.addEventListener("resize", measureFit);
    return () => window.removeEventListener("resize", measureFit);
  }, [mounted, measureFit]);

  React.useEffect(() => {
    if (expanded) listRef.current?.focus({ preventScroll: true });
  }, [expanded]);

  // Measure the pill and the panel; both can change with the model, effort or font loading.
  React.useLayoutEffect(() => {
    const trigger = triggerRef.current;
    if (!trigger) return;
    const measure = () => {
      const width = trigger.offsetWidth;
      const height = trigger.offsetHeight;
      setPill((p) =>
        p.width === width && p.height === height ? p : { width, height },
      );
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(trigger);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;
    const measure = () => setPanelHeight(panel.offsetHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(panel);
    return () => observer.disconnect();
  }, [mounted]);

  // The row highlight and the effort pill slide to where they belong.
  React.useLayoutEffect(() => {
    const row = rowRefs.current[active];
    if (!row) return;
    const top = row.offsetTop;
    setHighlight((h) =>
      h.top === top && h.ready === (h.ready || expanded)
        ? h
        : { top, ready: h.ready || expanded },
    );
  }, [active, expanded, mounted]);

  React.useLayoutEffect(() => {
    const i = efforts.indexOf(effort ?? "");
    const button = segmentRefs.current[i];
    if (!button) return;
    const left = button.offsetLeft;
    const width = button.offsetWidth;
    setSegment((s) =>
      s.left === left && s.width === width && s.ready === (s.ready || expanded)
        ? s
        : { left, width, ready: s.ready || expanded },
    );
  }, [effort, efforts, expanded, mounted, showEffort]);

  // Close on a click outside, or when focus leaves.
  React.useEffect(() => {
    if (!expanded) return;
    const onDown = (e: PointerEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) close(false);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [expanded, close]);

  const choose = (model: ModelOption) => {
    if (model.locked) {
      onLockedSelect?.(model);
      if (onLockedSelect) close();
      return;
    }
    onValueChange(model.id);
    close();
  };

  const onListKey = (e: React.KeyboardEvent) => {
    const last = models.length - 1;
    const move = (to: number) => {
      e.preventDefault();
      setActive(Math.max(0, Math.min(last, to)));
    };
    if (e.key === "ArrowDown") move(active === last ? 0 : active + 1);
    else if (e.key === "ArrowUp") move(active === 0 ? last : active - 1);
    else if (e.key === "Home") move(0);
    else if (e.key === "End") move(last);
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (models[active]) choose(models[active]);
    }
  };

  const onEffortKey = (e: React.KeyboardEvent) => {
    if (!onEffortChange || (e.key !== "ArrowRight" && e.key !== "ArrowLeft"))
      return;
    e.preventDefault();
    const i = efforts.indexOf(effort ?? "");
    const next =
      (i + (e.key === "ArrowRight" ? 1 : -1) + efforts.length) % efforts.length;
    onEffortChange(efforts[next]);
    segmentRefs.current[next]?.focus();
  };

  const width = expanded ? fit.width : pill.width;
  const height = expanded ? panelHeight : pill.height;
  const listId = `${id}-list`;

  return (
    <div
      ref={wrapRef}
      className={`relative inline-flex ${className}`}
      onKeyDown={(e) => {
        setQuietFocus(false);
        if (e.key === "Escape" && expanded) {
          e.preventDefault();
          close();
        }
      }}
      onBlur={(e) => {
        if (expanded && !wrapRef.current?.contains(e.relatedTarget as Node))
          close(false);
      }}
      {...props}
    >
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="listbox"
        aria-expanded={expanded}
        aria-controls={mounted ? listId : undefined}
        aria-label={`${label}: ${selected?.name ?? "none"}${selected?.reasoning && effort ? `, ${effort} thinking` : ""}`}
        disabled={disabled}
        onClick={() => (expanded ? close() : open())}
        onPointerDown={() => setQuietFocus(true)}
        onKeyDown={() => setQuietFocus(false)}
        onBlur={() => setQuietFocus(false)}
        className={`cursor-pointer disabled:cursor-default inline-flex h-8 items-center gap-1.5 rounded-full px-3 text-[12.5px] font-medium transition-colors duration-150 hover:bg-accent disabled:pointer-events-none disabled:opacity-50 ${quietFocus ? "outline-none" : FOCUS} ${expanded ? "bg-accent" : ""}`}
      >
        <PillLabel model={selected} effort={effort} reduced={reduced} />
        {/* Points up while the panel is open; the panel's copy of the pill turns in step. */}
        <ChevronDown
          aria-hidden="true"
          className="size-3.5 text-muted-foreground"
          style={{
            transform: expanded ? "rotate(180deg)" : "none",
            transition: reduced ? "none" : `transform 320ms ${EASE}`,
          }}
        />
      </button>

      {mounted && (
        <div
          // Clicks inside keep focus where it is, so the panel only closes when you leave it.
          onPointerDown={(e) => {
            e.preventDefault();
            setQuietFocus(true);
          }}
          className="absolute z-50 overflow-hidden bg-popover text-popover-foreground"
          style={{
            [side === "top" ? "bottom" : "top"]: expanded ? fit.lift : 0,
            [align === "start" ? "left" : "right"]: expanded
              ? align === "start"
                ? fit.shift
                : -fit.shift
              : 0,
            width,
            height,
            borderRadius: expanded ? 20 : pill.height / 2,
            boxShadow: expanded
              ? "0 0 0 1px var(--border)"
              : "0 0 0 1px transparent",
            transition: reduced
              ? "none"
              : `width ${DURATION}ms ${EASE}, height ${DURATION}ms ${EASE}, left ${DURATION}ms ${EASE}, right ${DURATION}ms ${EASE}, top ${DURATION}ms ${EASE}, bottom ${DURATION}ms ${EASE}, border-radius ${DURATION}ms ${EASE}, box-shadow 240ms ${EASE}`,
          }}
        >
          {/* The pill's label, fading out as the surface grows (and back in as it folds). */}
          <span
            aria-hidden="true"
            className={`pointer-events-none absolute inline-flex h-8 items-center gap-1.5 px-3 text-[12.5px] font-medium ${side === "top" ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
            style={{
              opacity: expanded ? 0 : 1,
              transition: reduced
                ? "none"
                : expanded
                  ? "opacity 120ms ease-out"
                  : "opacity 200ms ease-out 140ms",
            }}
          >
            <PillLabel model={selected} effort={effort} reduced={reduced} />
            {/* Turns with the surface: up as it opens, back down as it folds, so the hand-off to the pill never flips. */}
            <ChevronDown
              className="size-3.5 text-muted-foreground"
              style={{
                transform: expanded ? "rotate(180deg)" : "none",
                transition: reduced ? "none" : `transform 320ms ${EASE}`,
              }}
            />
          </span>

          <div
            ref={panelRef}
            inert={!expanded}
            className={`absolute p-1.5 ${side === "top" ? "bottom-0" : "top-0"} ${align === "start" ? "left-0" : "right-0"}`}
            style={{
              width: fit.width,
              opacity: expanded ? 1 : 0,
              transform: expanded
                ? "none"
                : `translateY(${side === "top" ? 6 : -6}px)`,
              transition: reduced
                ? "none"
                : expanded
                  ? `opacity 240ms ease-out 110ms, transform ${DURATION}ms ${EASE}`
                  : "opacity 100ms ease-out, transform 200ms ease-out",
            }}
          >
            <div className="flex h-7 items-center gap-3 px-2.5 text-[11px] text-muted-foreground">
              <span className="flex-1">{label}</span>
              {models.some(
                (m) => m.speed != null || m.intelligence != null,
              ) && (
                <>
                  <span className="w-[38px] text-center">Speed</span>
                  <span className="w-[38px] text-center">Smarts</span>
                </>
              )}
              <span className="w-7" />
            </div>

            <div
              ref={listRef}
              id={listId}
              role="listbox"
              tabIndex={0}
              aria-label={`${label}s`}
              aria-activedescendant={`${id}-model-${active}`}
              onKeyDown={onListKey}
              className="relative rounded-[14px] outline-none"
            >
              <span
                aria-hidden="true"
                className="absolute inset-x-0 top-0 h-12 rounded-[14px] bg-accent"
                style={{
                  transform: `translateY(${highlight.top}px)`,
                  transition:
                    highlight.ready && !reduced
                      ? `transform 200ms ${EASE}`
                      : "none",
                }}
              />
              {models.map((model, i) => {
                const isSelected = model.id === value;
                return (
                  <div
                    key={model.id}
                    ref={(el) => {
                      rowRefs.current[i] = el;
                    }}
                    id={`${id}-model-${i}`}
                    role="option"
                    aria-selected={isSelected}
                    aria-disabled={
                      model.locked && !onLockedSelect ? true : undefined
                    }
                    onPointerMove={() => i !== active && setActive(i)}
                    onClick={() => choose(model)}
                    className={`relative flex h-12 cursor-pointer items-center gap-3 rounded-[14px] px-2.5 ${model.locked && !onLockedSelect ? "cursor-default opacity-50" : ""}`}
                  >
                    {model.icon && (
                      <span
                        aria-hidden="true"
                        className="flex size-4 shrink-0 items-center justify-center text-muted-foreground [&_svg]:size-4 [&_svg]:stroke-[1.8]"
                      >
                        {model.icon}
                      </span>
                    )}
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-[13px] font-medium text-foreground">
                        {model.name}
                      </span>
                      {model.description && (
                        <span className="block truncate text-[11.5px] text-muted-foreground">
                          {model.description}
                        </span>
                      )}
                    </span>
                    {/* Speed and smarts only for options that have them (a permissions list doesn't). */}
                    {(model.speed != null || model.intelligence != null) && (
                      <>
                        <Meter value={model.speed} label="Speed" />
                        <Meter value={model.intelligence} label="Smarts" />
                      </>
                    )}
                    <span className="flex w-7 shrink-0 justify-end">
                      {model.locked ? (
                        <span className="rounded-full bg-muted px-1.5 py-px text-[10.5px] font-medium text-muted-foreground">
                          Pro
                        </span>
                      ) : isSelected ? (
                        <Check
                          aria-hidden="true"
                          className="size-3.5 text-foreground"
                          strokeWidth={2.2}
                        />
                      ) : null}
                    </span>
                  </div>
                );
              })}
            </div>

            {showEffort && (
              <div className="mt-1.5 flex items-center justify-between gap-3 border-t border-border/70 px-2.5 pb-1 pt-2.5 animate-[ui-fade-in_200ms_ease-out_both]">
                <span
                  id={`${id}-effort`}
                  className="text-[12px] text-muted-foreground"
                >
                  Thinking
                </span>
                <div
                  role="radiogroup"
                  aria-labelledby={`${id}-effort`}
                  onKeyDown={onEffortKey}
                  className="relative flex rounded-full bg-muted p-0.5"
                >
                  <span
                    aria-hidden="true"
                    className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                    style={{
                      width: segment.width,
                      transform: `translateX(${segment.left}px)`,
                      transition:
                        segment.ready && !reduced
                          ? `transform 240ms ${EASE}, width 240ms ${EASE}`
                          : "none",
                    }}
                  />
                  {efforts.map((level, i) => (
                    <button
                      key={level}
                      ref={(el) => {
                        segmentRefs.current[i] = el;
                      }}
                      type="button"
                      role="radio"
                      aria-checked={level === effort}
                      tabIndex={level === effort ? 0 : -1}
                      onClick={() => onEffortChange?.(level)}
                      className={`cursor-pointer relative h-6 rounded-full px-2.5 text-[11.5px] font-medium transition-colors ${FOCUS} ${level === effort ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                    >
                      {level}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

